  cparams.typesize = 4;
  cparams.compcode = BLOSC_BLOSCLZ;
  cparams.clevel = 5;
  blosc2_dparams dparams = BLOSC2_DPARAMS_DEFAULTS;
  blosc2_schunk* schunk = blosc2_schunk_new(&cparams);
